use super::*;
use std::{fs,path::PathBuf,time::Duration};
use crate::fiscal_repository::{Repository,Policy};
use nomina_fiscal_package::wire::Capability;
fn id()->String{uuid::Uuid::new_v4().to_string()}
struct Qa{root:PathBuf,service:Arc<ActivationService>,owner:Owner,iid:String}
impl Qa{fn new()->Self{let root=std::env::temp_dir().join("opencode").join(format!("5b7-5d3b2-4b-service-{}",id()));let repo=Repository::new(root.clone(),Policy::import_qa());repo.initialize_new().unwrap();let f=|n:&str|fs::read(std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../docs/evidence/5d3b2/fixtures").join(n)).unwrap();repo.accept_trust_episode(&id(),0,&[f("trust.json")]).unwrap();let iid=repo.record_verified_installation(&id(),1,&f("package1.nomina-fiscal"),&[Capability::Direct,Capability::Inverse]).unwrap().installation_id.unwrap();let imports=Arc::new(ImportService::new(repo,true));let owner=imports.owner("main",99).unwrap();Self{root,service:Arc::new(ActivationService::new(imports)),owner,iid}}
fn prepare(&self)->State{let s=self.service.reserve(&self.owner).unwrap();self.service.prepare(&self.owner,&s.session_id,ActivationIntent::Admit,Some(&self.iid),None,None).unwrap()}}
impl Drop for Qa{fn drop(&mut self){let _=fs::remove_dir_all(&self.root);}}
#[test]fn preview_and_confirm_are_separate_and_duplicate_is_idempotent(){let q=Qa::new();let before=q.service.imports.repository.open_existing().unwrap().generation;let p=q.prepare();assert_eq!(p.phase,"ready");assert_eq!(q.service.imports.repository.open_existing().unwrap().generation,before);let done=q.service.confirm(&q.owner,&p.session_id,p.preview_nonce.as_ref().unwrap()).unwrap();assert_eq!(done.phase,"committed");assert_eq!(q.service.confirm(&q.owner,&p.session_id,p.preview_nonce.as_ref().unwrap()).unwrap().receipt,done.receipt);}
#[test]fn invalid_nonce_and_foreign_owner_are_rejected(){let q=Qa::new();let p=q.prepare();assert_eq!(q.service.confirm(&q.owner,&p.session_id,&id()).unwrap_err().code,"PREVIEW_NONCE_MISMATCH");let mut other=q.owner.clone();other.incarnation=id();assert_eq!(q.service.get(&other,&p.session_id).unwrap_err().code,"SESSION_OWNER_MISMATCH");}
#[test]fn cancel_and_late_preparation_cannot_be_confirmed(){let q=Qa::new();let p=q.prepare();q.service.cancel(&q.owner,&p.session_id).unwrap();assert!(q.service.confirm(&q.owner,&p.session_id,p.preview_nonce.as_ref().unwrap()).is_err());let pending=q.service.reserve(&q.owner).unwrap();q.service.cancel(&q.owner,&pending.session_id).unwrap();assert_eq!(q.service.prepare(&q.owner,&pending.session_id,ActivationIntent::Admit,Some(&q.iid),None,None).unwrap().phase,"cancelled");}
#[test]fn absolute_and_idle_ttl_do_not_renew_by_polling(){for(a,i)in [(300,0),(0,120)]{let q=Qa::new();let p=q.prepare();q.service.age(&p.session_id,Duration::from_secs(a),Duration::from_secs(i));assert_eq!(q.service.get(&q.owner,&p.session_id).unwrap().phase,"expired");assert!(q.service.confirm(&q.owner,&p.session_id,p.preview_nonce.as_ref().unwrap()).is_err());}}
#[test]fn reload_cancels_pending_preview_and_changes_owner(){let q=Qa::new();let p=q.prepare();q.service.imports.navigation("main",true);q.service.navigation("main");q.service.imports.navigation("main",false);let next=q.service.imports.owner("main",99).unwrap();assert_ne!(next,q.owner);assert_eq!(q.service.get(&next,&p.session_id).unwrap_err().code,"SESSION_OWNER_MISMATCH");}
#[test]fn owner_capacity_and_cancel_release_slots(){let q=Qa::new();let a=q.prepare();q.prepare();assert_eq!(q.service.reserve(&q.owner).unwrap_err().code,"SESSION_CAPACITY");q.service.cancel(&q.owner,&a.session_id).unwrap();assert!(q.service.reserve(&q.owner).is_ok());}
#[test]fn repository_change_marks_confirmation_stale(){let q=Qa::new();let p=q.prepare();let g=q.service.imports.repository.open_existing().unwrap().generation;let f=fs::read(std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../docs/evidence/5d3b2/fixtures/trust.json")).unwrap();q.service.imports.repository.accept_trust_episode(&id(),g,&[f]).unwrap();assert_eq!(q.service.confirm(&q.owner,&p.session_id,p.preview_nonce.as_ref().unwrap()).unwrap().phase,"stale");}
#[test]fn closed_dtos_reject_frontend_authority_paths_and_extra_operations(){for s in [r#"{"intent":"admit","installationId":"x","authorized":true}"#,r#"{"intent":"select","installationId":"x","operations":["inverse"]}"#,r#"{"intent":"select","installationId":"x","path":"C:/fake"}"#]{assert!(serde_json::from_str::<PrepareRequest>(s).is_err());}assert!(serde_json::from_str::<Empty>(r#"{"activate":true}"#).is_err());}
#[test]fn normal_profile_remains_closed_without_creating_external_storage(){let root=std::env::temp_dir().join("opencode").join(format!("5d3b4b-prod-{}",id()));let imports=Arc::new(ImportService::new(Repository::new(root.clone(),Policy::production()),false));let owner=imports.owner("main",99).unwrap();let service=ActivationService::new(imports);assert_eq!(service.reserve(&owner).unwrap_err().code,"PRODUCTION_BOOTSTRAP_MISSING");assert_eq!(service.selection().unwrap_err().code,"PRODUCTION_BOOTSTRAP_MISSING");assert!(!root.exists());}
